package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided, and a steward may void a SETTLED claim
 * within 7 days of its settlement. A DRAFT claim may be deleted (-> DELETED, counting nowhere) and, on the same
 * sheet-today, restored (-> DRAFT).
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;

    /** Whether a claim in this status may move to the target status. */
    public boolean canBecome(ClaimStatus target) {
        return switch (target) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }

    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.voidreason.VoidReasons;

public class ValidateClaimStatus {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimStatusRequest request, Out<ValidClaimStatus> body, Settings settings,
            VoidReasons voidReasons)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String action = request.action() == null ? "" : request.action().trim();
        String reason = request.reason() == null ? "" : request.reason().trim();
        ValidClaimStatus valid = switch (action) {
            case "open" -> new ValidClaimStatus(ClaimStatus.OPEN, request.user(), ValidClaimStatus.Decision.NONE, null);
            case "settle" -> new ValidClaimStatus(ClaimStatus.SETTLED, request.user(), ValidClaimStatus.Decision.NONE, null);
            case "void" -> {
                // While the sheet has void reasons, a void needs one chosen from them; without any, none is kept.
                if (voidReasons.list(sheetId).isEmpty()) {
                    yield new ValidClaimStatus(ClaimStatus.VOID, request.user(), ValidClaimStatus.Decision.NONE, null);
                }
                if (reason.isEmpty() || !voidReasons.contains(sheetId, reason)) {
                    throw new InvalidClaimException("A void needs a reason from the sheet's list");
                }
                yield new ValidClaimStatus(ClaimStatus.VOID, request.user(), ValidClaimStatus.Decision.NONE, reason);
            }
            case "delete" -> new ValidClaimStatus(ClaimStatus.DELETED, request.user(), ValidClaimStatus.Decision.NONE, null);
            case "restore" -> new ValidClaimStatus(ClaimStatus.DRAFT, request.user(), ValidClaimStatus.Decision.NONE, null);
            case "approve" -> new ValidClaimStatus(ClaimStatus.SETTLED, request.user(), ValidClaimStatus.Decision.APPROVE, null);
            case "reject" -> {
                if (reason.isEmpty()) throw new InvalidClaimException("A rejection needs a reason");
                yield new ValidClaimStatus(ClaimStatus.OPEN, request.user(), ValidClaimStatus.Decision.REJECT, reason);
            }
            default -> throw new InvalidClaimException("No such status change: " + action);
        };
        body.set(valid);
    }
}
package net.officefloor.hq.app.claim;

/** A status change that names a known action: its target status, whether it is a steward's decision
 *  on a PENDING claim (approve or reject), and the reason given to reject (or chosen from the sheet's list to void; null for none). */
public record ValidClaimStatus(ClaimStatus target, String user, Decision decision, String reason) {

    /** A steward's decision on a PENDING claim; NONE for any other status change. */
    public enum Decision { NONE, APPROVE, REJECT }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.plugin.variable.Val;

public class AuditClaimStatus {
    public void audit(@Val ValidClaimStatus request, @Val Claim claim, @Val ClaimNumber number, People people, Audit audit, @Val RollupFigures before, Rollup rollup, ClaimLog log, Watches watches) {
        record(request, claim, number, people, audit, before, rollup, log, watches);
    }

    /** Logs and audits a status change that went through, as a single change does. Bulk settle uses it too. */
    static void record(ValidClaimStatus request, Claim claim, ClaimNumber number, People people, Audit audit, RollupFigures before, Rollup rollup, ClaimLog log, Watches watches) {
        String event = switch (request.decision()) {
            case APPROVE -> "CLAIM_APPROVED";
            case REJECT -> "CLAIM_REJECTED";
            case NONE -> switch (claim.getStatus()) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DELETED -> "CLAIM_DELETED";
                case DRAFT -> "CLAIM_RESTORED";
            };
        };
        net.officefloor.hq.app.person.Person person = people.find(claim.getSheetId(), claim.getPersonId());
        // Read before this change's own line is logged.
        boolean voidedSettled = claim.getStatus() == ClaimStatus.VOID
                && ClaimStatus.SETTLED.name().equals(log.lastStatus(claim));
        log.record(claim, person, request.user());
        String line = ClaimAudit.line(event, request.user(), person, claim, number.value());
        if (voidedSettled) {
            // A voided SETTLED claim reverses its frozen figure out of every total.
            line += " reversed=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (request.decision() == ValidClaimStatus.Decision.REJECT) {
            line += " reason=" + request.reason();
        }
        if (claim.getStatus() == ClaimStatus.VOID && request.reason() != null) {
            line += " reason=" + request.reason();
        }
        audit.recordOnCommit(line);
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            // Settled or approved: each user watching the person is notified, after the claim's own line.
            watches.notifyWatchers(person, request.user(), number.value(), audit);
        }
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
